pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut arr = input.as_array().unwrap();
    let mut result = Vec::new();
    let mut prev_finish = 0i64;

    for item in arr {
        let arr = item.as_array().unwrap();
        let arrival = arr[0].as_i64().unwrap();
        let duration = arr[1].as_i64().unwrap();
        let finish = arrival.max(prev_finish) + duration;
        prev_finish = finish;
        result.push(finish);
    }

    serde_json::json!(result)
}
